//! Additional immutable-C6 P2 controls; not full Escrow/Genesis/settlement acceptance.
#[path="support/surplus_registry.rs"] mod f;
use revm::{DatabaseCommit,InMemoryDB,primitives::{Address,U256,Bytecode,Bytes}};
use pocol_lp4_execution::{pay::{registry_address,escrow_address},output};
fn dump(db:&InMemoryDB)->serde_json::Value{let mut m=serde_json::Map::new();for(a,v)in &db.accounts{if v.account_state==revm::db::AccountState::NotExisting{continue}let code=db.contracts.get(&v.info.code_hash).map(|b|b.original_bytes()).unwrap_or_default();let storage=v.storage.iter().filter(|(_,v)|**v!=U256::ZERO).map(|(k,v)|(format!("0x{k:064x}"),serde_json::json!(format!("0x{v:064x}")))).collect::<serde_json::Map<_,_>>();m.insert(format!("{a:#x}"),serde_json::json!({"nonce":v.info.nonce,"balance":v.info.balance.to_string(),"code":format!("0x{}",code.iter().map(|b|format!("{b:02x}")).collect::<String>()),"storage":storage}));}serde_json::Value::Object(m)}
fn step(rows:&mut Vec<serde_json::Value>,db:&mut InMemoryDB,name:&str,caller:Address,to:Address,data:Vec<u8>,value:u64,height:u64)->bool{let pre=dump(db);let r=f::call(db,caller,to,data.clone(),U256::from(value),height);let success=r.result.is_success();let gas=r.result.gas_used();let bytes=output(&r.result).to_vec();let logs=r.result.logs().len();db.commit(r.state);rows.push(serde_json::json!({"name":name,"caller":format!("{caller:#x}"),"to":format!("{to:#x}"),"input":data,"value":value,"height":height,"pre":pre,"post":dump(db),"success":success,"gasUsed":gas,"output":bytes,"logs":logs}));success}
fn phases(rows:&mut Vec<serde_json::Value>,db:&mut InMemoryDB,h:u64){for sig in ["markClose()","beginBlock()"]{assert!(step(rows,db,sig,f::system(),registry_address(),f::selector(sig),0,h));}}
pub fn cases()->Vec<serde_json::Value>{let mut rows=Vec::new();let artifact:serde_json::Value=serde_json::from_str(include_str!("data/force-surplus.json")).unwrap();let hex=artifact["output"]["contracts"]["ForceSurplus.sol"]["ForceSurplus"]["evm"]["deployedBytecode"]["object"].as_str().unwrap();let code=Bytecode::new_raw(Bytes::from(hex.as_bytes().chunks(2).map(|c|u8::from_str_radix(std::str::from_utf8(c).unwrap(),16).unwrap()).collect::<Vec<_>>()));
 for closing in [false,true]{let mut db=f::fixture();phases(&mut rows,&mut db,1);let mut registration=f::selector("register(address)");registration.extend(f::addr(0x32).into_word());assert!(step(&mut rows,&mut db,"register-second-active",f::addr(0x12),registry_address(),registration,10,1));
  for (source,target,amount) in [(f::addr(0x55),escrow_address(),1000u64),(f::addr(0x56),registry_address(),700)]{
   f::insert(&mut db,source,U256::from(amount),1,code.clone());let mut data=f::selector("force(address)");data.extend(target.into_word());assert!(step(&mut rows,&mut db,"forced-transfer",f::addr(0x12),source,data,0,1));assert_eq!(db.accounts[&source].info.balance,U256::ZERO);assert_ne!(db.accounts[&source].info.code_hash,revm::primitives::KECCAK_EMPTY);assert_eq!(f::reg(&db,4),U256::from(20));
  }
  assert_eq!(db.accounts[&escrow_address()].info.balance,U256::from(1020));assert_eq!(db.accounts[&registry_address()].info.balance,U256::from(700));
  let mut data=f::selector("releaseBond(address)");data.extend(f::addr(0x11).into_word());assert!(!step(&mut rows,&mut db,"unauthorized-release",f::addr(0x12),escrow_address(),data.clone(),0,1));assert!(!step(&mut rows,&mut db,"unauthorized-value-release",f::addr(0x12),escrow_address(),data,1,1));assert!(!step(&mut rows,&mut db,"ordinary-value-reverts",f::addr(0x12),escrow_address(),vec![],1,1));
  if closing{f::put(&mut db,f::caps(),U256::from(47),U256::from(2));phases(&mut rows,&mut db,2);}else{assert!(step(&mut rows,&mut db,"exit",f::addr(0x11),registry_address(),f::selector("deregister()"),0,1));phases(&mut rows,&mut db,4);assert!(step(&mut rows,&mut db,"claim-exact-held",f::addr(0x11),registry_address(),f::selector("claimBond()"),0,4));}
  let remaining=if closing{0u64}else{10};assert_eq!(f::reg(&db,4),U256::from(remaining));assert_eq!(db.accounts[&f::addr(0x31)].info.balance,U256::from(10));assert_eq!(db.accounts[&escrow_address()].info.balance,U256::from(1000+remaining));assert_eq!(db.accounts[&registry_address()].info.balance,U256::from(700));
 }
 rows}
#[test] fn actual_forced_surplus_stays_locked_outside_held_and_refunds(){assert_eq!(cases().len(),22);}
